def find_special_columns(grid):
    n = len(grid)
    cols_with_triple = set()
    for r in range(n):
        vals = grid[r]
        freq = {}
        for c in range(n):
            v = vals[c]
            if v != 0:
                freq[v] = freq.get(v, 0) + 1
        same_positions = [c for v, count in freq.items() if count >= 3 for c in range(n) if vals[c] == v]
        if len(same_positions) >= 3:
            cols_with_triple.update(same_positions)
    return sorted(cols_with_triple)

# Apply transformation rule
def apply_between_rule(grid):
    n = len(grid)
    result = [row[:] for row in grid]

    special_cols = find_special_columns(grid)

    for col in special_cols:
        nz = [(r, grid[r][col]) for r in range(n) if grid[r][col] != 0]
        nz.sort(key=lambda x: x[0])

        for i, (r_src, val) in enumerate(nz):
            if i == 0:
                # First one: fill upward to top boundary
                r = r_src - 1
                while r >= 0:
                    if result[r][col] != 0:
                        break
                    result[r][col] = val
                    r -= 1
            elif i == len(nz) - 1:
                # Last one: fill BOTH directions
                # Upward
                r = r_src - 1
                while r > 0:
                    if result[r][col] != 0:
                        break
                    result[r][col] = val
                    r -= 1
                # Downward
                r = r_src + 1
                while r < n:
                    if result[r][col] != 0:
                        break
                    result[r][col] = val
                    r += 1
            else:
                # Middle one: fill gap BETWEEN previous and next non-zero
                prev_r = nz[i-1][0]
                next_r = nz[i+1][0]

                r_start = prev_r + 1
                r_end = next_r - 1

                r = r_start
                while r <= r_end:
                    if result[r][col] != 0:
                        break
                    result[r][col] = val
                    r += 1

    return result

